using System.Text.Json;
using Kgp.Infrastructure.Persistence;

namespace Kgp.Tests;

/// <summary>
/// Guards the real data/osm files (generated by data/scripts/import_osm.py). Passes vacuously while they don't exist yet.
/// </summary>
public class OsmDataFileTests
{
    private static readonly string Dir = Path.Combine(AppContext.BaseDirectory, "data", "osm");

    public static TheoryData<string> Files => new() { OsmSeeder.ParkingFileName, OsmSeeder.TrailsFileName };

    [Theory]
    [MemberData(nameof(Files))]
    public void Every_feature_belongs_to_a_known_peak_and_has_an_osm_id(string file)
    {
        var path = Path.Combine(Dir, file);
        if (!File.Exists(path))
        {
            return; // Not generated yet.
        }

        var slugs = PeakSeeder.Load(Path.Combine(AppContext.BaseDirectory, "data", "peaks.json")).Select(p => p.Slug).ToHashSet();
        using var doc = JsonDocument.Parse(File.ReadAllBytes(path));
        Assert.Equal("FeatureCollection", doc.RootElement.GetProperty("type").GetString());

        foreach (var feature in doc.RootElement.GetProperty("features").EnumerateArray())
        {
            var props = feature.GetProperty("properties");
            var osmId = props.GetProperty("osmId").GetString();
            Assert.Matches("^(node|way|relation)/[0-9]+$", osmId);
            Assert.True(slugs.Contains(props.GetProperty("peakSlug").GetString()!), $"{file}: {osmId} has unknown peakSlug");
        }
    }
}
